"""Build static Garden pages from verified local DNA. No network or credentials."""
import sys
sys.exit(
    "Refusing to run: the .html files in this directory are now hand-edited and "
    "are the source of truth.\n"
    "This generator still emits the pre-rewrite copy (old titles and meta "
    "descriptions, kill-list wording, no canonical/OG/JSON-LD), so running it "
    "would silently revert the content pass.\n"
    "Port the changes into this script before removing this guard. "
    "See clients/chick-goodies/PLAN-CONTENT-STRATEGY.md section 4.1."
)

from pathlib import Path
from html import escape as e
import json
from urllib.parse import quote
from PIL import Image
P = Path(__file__).resolve().parent
facts = json.loads((P.parent / 'shared/facts.json').read_text(encoding='utf-8'))
assert '@' in facts['email'] and '[' not in facts['email'], 'Verified email required'
assert facts['phone'].isdigit(), 'Verified phone required'
menus = list(reversed(facts['menus']))
phone = facts['phone']
email = facts['email']
phone_display = f'({phone[-10:-7]}) {phone[-7:-4]}-{phone[-4:]}'
navs = [('index','The atelier'),('menu','The menu'),('gallery','The collection'),('story','Meet Tricia'),('enquire','Enquire')]
def image(name, alt, cls='', eager=False):
    w,h = Image.open(P/'img'/name).size
    return f'<img src="img/{name}" width="{w}" height="{h}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def mark():
    return '<a class="brand" href="index.html" aria-label="Charcuterie Chick home">'+image('brand.webp','The Chick Goodies — Charcuterie Chick',eager=True)+'</a>'
def contact():
    return f'<a href="tel:+{phone}">{phone_display}</a><a href="mailto:{e(email)}">{e(email)}</a>'
def page(route, title, desc, content):
    nav = ''.join(f'<a href="{key}.html"'+(' aria-current="page"' if key==route else '')+f'>{label}</a>' for key,label in navs)
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} | Charcuterie Chick</title><meta name="description" content="{desc}"><meta name="theme-color" content="#d5ddb9">
<link rel="icon" href="img/brand.webp" type="image/webp"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;1,400;1,500&family=Jost:wght@400;500;600&display=swap" rel="stylesheet">
<link rel="stylesheet" href="garden.css"><script src="garden.js" defer></script></head>
<body class="page-{route}"><a class="skip" href="#main">Skip to content</a>
<div class="ambient" aria-hidden="true"><canvas id="caustics"></canvas></div><span id="cursor" aria-hidden="true"></span>
<header class="masthead">{mark()}<nav aria-label="Main navigation">{nav}</nav></header>
<div class="utility"><span>Tomball, Texas · Made to gather</span><button id="motion" type="button" hidden aria-pressed="false">Pause motion <span aria-hidden="true">Ⅱ</span></button></div>
<main id="main">{content}</main>
<footer><div class="footer-invitation"><p class="eyebrow">A little conversation. A beautiful beginning.</p><a href="enquire.html">Shall we <i>gather?</i> <span aria-hidden="true">↗</span></a></div>
<div class="footer-bottom">{mark()}<div><p>Tomball · The Woodlands<br>Spring · Conroe</p><a href="https://www.instagram.com/charcuteriechickhtx/">Instagram ↗</a></div><div class="contact">{contact()}<small>Enquiries, not confirmed bookings.</small></div></div>
<div class="colophon"><span>Food &amp; hospitality, by Tricia Holfelder.</span><a href="#main">Back to top ↑</a></div></footer>
</body></html>'''
    (P/f'{route}.html').write_text(html,encoding='utf-8')

