collection=[('knot-hero.jpg','Gathered around the table','Grazing spread from The Chick Goodies event collection','wide'),('board-01.jpg','The small details','Charcuterie board from Tricia’s food collection','oval'),('cart-640.jpg','An occasion on wheels','Charcuterie cart from the catering collection','landscape'),('table-01.jpg','Room for a little more','Grazing table from the client event collection','tall'),('knot-4.jpg','Something to share','Food arrangement from The Chick Goodies collection','wide'),('sips-02.jpg','A toast to together','Beverage setup from the client collection','oval'),('sweets-01.jpg','A sweet ending','Sweets presentation from the client collection','tall'),('catering-1000.jpg','Company, beautifully kept','Catering presentation from Tricia’s collection','landscape')]
